; ================================================
    ORG $0000  ; Sequential bank model

; Function: update_player (Bank #1)
update_player:
    ; CLAMP: Clamp value to range [min, max]
    JSR J1X_BUILTIN
    STD RESULT
    PSHS D              ; save LEFT on stack (nested RIGHT)
    LDD #32
    STD TMPVAL          ; RIGHT → TMPVAL
    PULS D              ; restore LEFT into D
    TFR D,X             ; X = LEFT (dividend)
    LDD TMPVAL          ; D = RIGHT (divisor)
    JSR DIV16           ; D = X / D
    STD TMPPTR     ; Save value
    LDD #-4
    STD TMPPTR+2   ; Save min
    LDD #4
    STD TMPPTR+4   ; Save max
    LDD TMPPTR     ; Load value
    CMPD TMPPTR+2  ; Compare with min
    LBGE .CLAMP_0_CHK_MAX ; Branch if value >= min
    LDD TMPPTR+2
    STD RESULT
    LBRA .CLAMP_0_END
.CLAMP_0_CHK_MAX:
    LDD TMPPTR     ; Load value again
    CMPD TMPPTR+4  ; Compare with max
    LBLE .CLAMP_0_OK  ; Branch if value <= max
    LDD TMPPTR+4
    STD RESULT
    LBRA .CLAMP_0_END
.CLAMP_0_OK:
    LDD TMPPTR
    STD RESULT
.CLAMP_0_END:
    STD VAR_PLAYER_VX
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PLAYER_VX
    CMPD TMPVAL
    LBGT .CMP_55_TRUE
    LDD #0
    LBRA .CMP_55_END
.CMP_55_TRUE:
    LDD #1
.CMP_55_END:
    LBEQ IF_NEXT_113
    LDD #0
    STD VAR_PLAYER_FACING
    LBRA IF_END_112
IF_NEXT_113:
IF_END_112:
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PLAYER_VX
    CMPD TMPVAL
    LBLT .CMP_56_TRUE
    LDD #0
    LBRA .CMP_56_END
.CMP_56_TRUE:
    LDD #1
.CMP_56_END:
    LBEQ IF_NEXT_115
    LDD #1
    STD VAR_PLAYER_FACING
    LBRA IF_END_114
IF_NEXT_115:
IF_END_114:
    ; CLAMP: Clamp value to range [min, max]
    LDD >VAR_PLAYER_VX
    STD TMPVAL          ; RIGHT → TMPVAL (LEFT simple)
    LDD >VAR_PLAYER_X
    ADDD TMPVAL         ; D = LEFT + RIGHT
    STD TMPPTR     ; Save value
    LDD #-96  ; const WORLD_X_MIN
    STD TMPPTR+2   ; Save min
    LDD #95  ; const WORLD_X_MAX
    STD TMPPTR+4   ; Save max
    LDD TMPPTR     ; Load value
    CMPD TMPPTR+2  ; Compare with min
    LBGE .CLAMP_1_CHK_MAX ; Branch if value >= min
    LDD TMPPTR+2
    STD RESULT
    LBRA .CLAMP_1_END
.CLAMP_1_CHK_MAX:
    LDD TMPPTR     ; Load value again
    CMPD TMPPTR+4  ; Compare with max
    LBLE .CLAMP_1_OK  ; Branch if value <= max
    LDD TMPPTR+4
    STD RESULT
    LBRA .CLAMP_1_END
.CLAMP_1_OK:
    LDD TMPPTR
    STD RESULT
.CLAMP_1_END:
    STD VAR_PLAYER_X
    ; ===== LEVEL_COLLISION_X builtin =====
    LDD >VAR_PLAYER_X
    STD >LCOL_PX         ; store player world_x (16-bit)
    LDD #6  ; const PLAYER_HW
    STB >LCOL_PHW        ; store player half_width
    LDD #11  ; const PLAYER_HH
    STB >LCOL_PHH        ; store player half_height for Y-overlap check
    LDD >VAR_PLAYER_Y
    STD >LCOL_PY         ; store player_y (16-bit)
    JSR LEVEL_COLLISION_X_RUNTIME
    STD VAR_PUSH_DX
    LDD >VAR_PUSH_DX
    STD TMPVAL          ; RIGHT → TMPVAL (LEFT simple)
    LDD >VAR_PLAYER_X
    ADDD TMPVAL         ; D = LEFT + RIGHT
    STD VAR_PLAYER_X
    LDD #1
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PLAYER_ON_GROUND
    CMPD TMPVAL
    LBEQ .CMP_57_TRUE
    LDD #0
    LBRA .CMP_57_END
.CMP_57_TRUE:
    LDD #1
.CMP_57_END:
    LBEQ IF_NEXT_117
    LDA >$C80F   ; Vec_Btns_1: bit0=1 means btn1 pressed
    BITA #$01
    LBNE .J1B1_1_ON
    LDD #0
    LBRA .J1B1_1_END
.J1B1_1_ON:
    LDD #1
.J1B1_1_END:
    STD RESULT
    LBEQ IF_NEXT_119
    LDD #12  ; const JUMP_SPEED
    STD VAR_PLAYER_VY
    LDD #0
    STD VAR_PLAYER_ON_GROUND
    LBRA IF_END_118
IF_NEXT_119:
IF_END_118:
    LDD #1
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PLAYER_ON_GROUND
    CMPD TMPVAL
    LBEQ .CMP_58_TRUE
    LDD #0
    LBRA .CMP_58_END
.CMP_58_TRUE:
    LDD #1
.CMP_58_END:
    LBEQ IF_NEXT_121
    ; ===== LEVEL_COLLISION_Y builtin =====
    LDD >VAR_PLAYER_X
    STD >LCOL_PX         ; store player world_x (16-bit)
    LDD #11  ; const PLAYER_HH
    STB >LCOL_PHH        ; store player half_height
    LDD >VAR_PLAYER_Y
    ; Compute player_feet = player_y - player_hh (16-bit)
    STD >TMPVAL          ; save player_y
    LDB >LCOL_PHH        ; B = player_hh
    CLRA
    STD >LCOL_PY         ; reuse as scratch (16-bit hh)
    LDD >TMPVAL          ; D = player_y
    SUBD >LCOL_PY        ; D = player_y - player_hh = player_feet
    STD >LCOL_PY         ; store player_feet Y (16-bit) for surface filter
    JSR LEVEL_COLLISION_Y_RUNTIME
    STD VAR_FLOOR_Y
    LDD #127
    STD TMPVAL          ; RIGHT → TMPVAL (LEFT simple)
    LDD >VAR_CAMERA_Y
    SUBD TMPVAL         ; D = LEFT - RIGHT
    STD VAR_SCREEN_BOTTOM
    LDD >VAR_SCREEN_BOTTOM
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_FLOOR_Y
    CMPD TMPVAL
    LBLT .CMP_59_TRUE
    LDD #0
    LBRA .CMP_59_END
.CMP_59_TRUE:
    LDD #1
.CMP_59_END:
    LBEQ IF_NEXT_123
    LDD >VAR_SPAWN_FLOOR_Y
    STD VAR_FLOOR_Y
    LBRA IF_END_122
IF_NEXT_123:
IF_END_122:
    LDD >VAR_PLAYER_Y
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_FLOOR_Y
    CMPD TMPVAL
    LBLT .CMP_60_TRUE
    LDD #0
    LBRA .CMP_60_END
.CMP_60_TRUE:
    LDD #1
.CMP_60_END:
    LBEQ IF_NEXT_125
    LDD #0
    STD VAR_PLAYER_ON_GROUND
    LBRA IF_END_124
IF_NEXT_125:
IF_END_124:
    LBRA IF_END_120
IF_NEXT_121:
IF_END_120:
    LBRA IF_END_116
IF_NEXT_117:
IF_END_116:
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PLAYER_ON_GROUND
    CMPD TMPVAL
    LBEQ .CMP_61_TRUE
    LDD #0
    LBRA .CMP_61_END
.CMP_61_TRUE:
    LDD #1
.CMP_61_END:
    LBEQ IF_NEXT_127
    LDD #1  ; const GRAVITY
    STD TMPVAL          ; RIGHT → TMPVAL (LEFT simple)
    LDD >VAR_PLAYER_VY
    SUBD TMPVAL         ; D = LEFT - RIGHT
    STD VAR_PLAYER_VY
    LDD #12  ; const MAX_FALL_SPEED
    STD TMPVAL          ; RIGHT → TMPVAL (LEFT simple)
    LDD #-1
    TFR D,X             ; X = LEFT
    LDD TMPVAL          ; D = RIGHT
    JSR MUL16           ; D = X * D
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PLAYER_VY
    CMPD TMPVAL
    LBLT .CMP_62_TRUE
    LDD #0
    LBRA .CMP_62_END
.CMP_62_TRUE:
    LDD #1
.CMP_62_END:
    LBEQ IF_NEXT_129
    LDD #12  ; const MAX_FALL_SPEED
    STD TMPVAL          ; RIGHT → TMPVAL (LEFT simple)
    LDD #-1
    TFR D,X             ; X = LEFT
    LDD TMPVAL          ; D = RIGHT
    JSR MUL16           ; D = X * D
    STD VAR_PLAYER_VY
    LBRA IF_END_128
IF_NEXT_129:
IF_END_128:
    LDD >VAR_PLAYER_Y
    STD VAR_PREV_Y
    LDD >VAR_PLAYER_VY
    STD TMPVAL          ; RIGHT → TMPVAL (LEFT simple)
    LDD >VAR_PLAYER_Y
    ADDD TMPVAL         ; D = LEFT + RIGHT
    STD VAR_PLAYER_Y
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PLAYER_VY
    CMPD TMPVAL
    LBLT .CMP_63_TRUE
    LDD #0
    LBRA .CMP_63_END
.CMP_63_TRUE:
    LDD #1
.CMP_63_END:
    LBEQ IF_NEXT_131
    ; ===== LEVEL_COLLISION_Y builtin =====
    LDD >VAR_PLAYER_X
    STD >LCOL_PX         ; store player world_x (16-bit)
    LDD #11  ; const PLAYER_HH
    STB >LCOL_PHH        ; store player half_height
    LDD >VAR_PREV_Y
    ; Compute player_feet = player_y - player_hh (16-bit)
    STD >TMPVAL          ; save player_y
    LDB >LCOL_PHH        ; B = player_hh
    CLRA
    STD >LCOL_PY         ; reuse as scratch (16-bit hh)
    LDD >TMPVAL          ; D = player_y
    SUBD >LCOL_PY        ; D = player_y - player_hh = player_feet
    STD >LCOL_PY         ; store player_feet Y (16-bit) for surface filter
    JSR LEVEL_COLLISION_Y_RUNTIME
    STD VAR_FLOOR_Y
    LDD #127
    STD TMPVAL          ; RIGHT → TMPVAL (LEFT simple)
    LDD >VAR_CAMERA_Y
    SUBD TMPVAL         ; D = LEFT - RIGHT
    STD VAR_SCREEN_BOTTOM
    LDD >VAR_SCREEN_BOTTOM
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_FLOOR_Y
    CMPD TMPVAL
    LBLT .CMP_64_TRUE
    LDD #0
    LBRA .CMP_64_END
.CMP_64_TRUE:
    LDD #1
.CMP_64_END:
    LBEQ IF_NEXT_133
    LDD >VAR_SPAWN_FLOOR_Y
    STD VAR_FLOOR_Y
    LBRA IF_END_132
IF_NEXT_133:
IF_END_132:
    LDD >VAR_FLOOR_Y
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PLAYER_Y
    CMPD TMPVAL
    LBLE .CMP_65_TRUE
    LDD #0
    LBRA .CMP_65_END
.CMP_65_TRUE:
    LDD #1
.CMP_65_END:
    LBEQ IF_NEXT_135
    LDD >VAR_FLOOR_Y
    STD VAR_PLAYER_Y
    LDD #0
    STD VAR_PLAYER_VY
    LDD #1
    STD VAR_PLAYER_ON_GROUND
    LBRA IF_END_134
IF_NEXT_135:
IF_END_134:
    LBRA IF_END_130
IF_NEXT_131:
IF_END_130:
    LBRA IF_END_126
IF_NEXT_127:
IF_END_126:
    LDD #127  ; const WORLD_Y_MAX
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PLAYER_Y
    CMPD TMPVAL
    LBGT .CMP_66_TRUE
    LDD #0
    LBRA .CMP_66_END
.CMP_66_TRUE:
    LDD #1
.CMP_66_END:
    LBEQ IF_NEXT_137
    LDD #127  ; const WORLD_Y_MAX
    STD VAR_PLAYER_Y
    LDD #0
    STD VAR_PLAYER_VY
    LBRA IF_END_136
IF_NEXT_137:
IF_END_136:
    LDD >VAR_SPAWN_FLOOR_Y
    STD VAR_SCREEN_FLOOR
    LDD >VAR_SCREEN_FLOOR
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PLAYER_Y
    CMPD TMPVAL
    LBLT .CMP_67_TRUE
    LDD #0
    LBRA .CMP_67_END
.CMP_67_TRUE:
    LDD #1
.CMP_67_END:
    LBEQ IF_NEXT_139
    LDD >VAR_SCREEN_FLOOR
    STD VAR_PLAYER_Y
    LDD #0
    STD VAR_PLAYER_VY
    LDD #1
    STD VAR_PLAYER_ON_GROUND
    LBRA IF_END_138
IF_NEXT_139:
IF_END_138:
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_SHOOT_COOLDOWN
    CMPD TMPVAL
    LBGT .CMP_68_TRUE
    LDD #0
    LBRA .CMP_68_END
.CMP_68_TRUE:
    LDD #1
.CMP_68_END:
    LBEQ IF_NEXT_141
    LDD #1
    STD TMPVAL          ; RIGHT → TMPVAL (LEFT simple)
    LDD >VAR_SHOOT_COOLDOWN
    SUBD TMPVAL         ; D = LEFT - RIGHT
    STD VAR_SHOOT_COOLDOWN
    LBRA IF_END_140
IF_NEXT_141:
IF_END_140:
    LDA >$C80F   ; Vec_Btns_1: bit1=1 means btn2 pressed
    BITA #$02
    LBNE .J1B2_2_ON
    LDD #0
    LBRA .J1B2_2_END
.J1B2_2_ON:
    LDD #1
.J1B2_2_END:
    STD RESULT
    LBEQ IF_NEXT_143
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_SHOOT_COOLDOWN
    CMPD TMPVAL
    LBEQ .CMP_69_TRUE
    LDD #0
    LBRA .CMP_69_END
.CMP_69_TRUE:
    LDD #1
.CMP_69_END:
    LBEQ IF_NEXT_145
    LDD #0
    STD VAR_BALL_LAUNCHED
    JSR TRAMP_try_launch_ball  ; cross-bank trampoline (bank #1 -> bank #0)
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_BALL_LAUNCHED
    CMPD TMPVAL
    LBEQ .CMP_70_TRUE
    LDD #0
    LBRA .CMP_70_END
.CMP_70_TRUE:
    LDD #1
.CMP_70_END:
    LBEQ IF_NEXT_147
    LDD #5  ; const SNOW_SPEED
    STD VAR_SNOW_SPAWN_VX
    LDD #1
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PLAYER_FACING
    CMPD TMPVAL
    LBEQ .CMP_71_TRUE
    LDD #0
    LBRA .CMP_71_END
.CMP_71_TRUE:
    LDD #1
.CMP_71_END:
    LBEQ IF_NEXT_149
    LDD #5  ; const SNOW_SPEED
    STD TMPVAL          ; RIGHT → TMPVAL (LEFT simple)
    LDD #-1
    TFR D,X             ; X = LEFT
    LDD TMPVAL          ; D = RIGHT
    JSR MUL16           ; D = X * D
    STD VAR_SNOW_SPAWN_VX
    LBRA IF_END_148
IF_NEXT_149:
IF_END_148:
    JSR try_shoot
    LBRA IF_END_146
IF_NEXT_147:
IF_END_146:
    LBRA IF_END_144
IF_NEXT_145:
IF_END_144:
    LBRA IF_END_142
IF_NEXT_143:
IF_END_142:
    RTS

; Function: try_shoot (Bank #1)
try_shoot:
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_SNOW0_ACTIVE
    CMPD TMPVAL
    LBEQ .CMP_75_TRUE
    LDD #0
    LBRA .CMP_75_END
.CMP_75_TRUE:
    LDD #1
.CMP_75_END:
    LBEQ IF_NEXT_157
    LDD >VAR_PLAYER_X
    STD VAR_SNOW0_X
    LDD >VAR_PLAYER_Y
    STD VAR_SNOW0_Y
    LDD >VAR_SNOW_SPAWN_VX
    STD VAR_SNOW0_VX
    LDD #3  ; const SNOW_LAUNCH_VY
    STD VAR_SNOW0_VY
    LDD >VAR_SNOW_LIFE_MAX
    STD VAR_SNOW0_LIFE
    LDD #1
    STD VAR_SNOW0_ACTIVE
    LDD #15  ; const SHOOT_COOLDOWN_MAX
    STD VAR_SHOOT_COOLDOWN
    ; PLAY_SFX("shot_normal") - play SFX asset (index=0)
    LDX #0        ; SFX asset index for lookup
    JSR PLAY_SFX_BANKED  ; Play with automatic bank switching
    LDD #0
    STD RESULT
    LBRA IF_END_156
IF_NEXT_157:
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_SNOW1_ACTIVE
    CMPD TMPVAL
    LBEQ .CMP_76_TRUE
    LDD #0
    LBRA .CMP_76_END
.CMP_76_TRUE:
    LDD #1
.CMP_76_END:
    LBEQ IF_NEXT_159
    LDD >VAR_PLAYER_X
    STD VAR_SNOW1_X
    LDD >VAR_PLAYER_Y
    STD VAR_SNOW1_Y
    LDD >VAR_SNOW_SPAWN_VX
    STD VAR_SNOW1_VX
    LDD #3  ; const SNOW_LAUNCH_VY
    STD VAR_SNOW1_VY
    LDD >VAR_SNOW_LIFE_MAX
    STD VAR_SNOW1_LIFE
    LDD #1
    STD VAR_SNOW1_ACTIVE
    LDD #15  ; const SHOOT_COOLDOWN_MAX
    STD VAR_SHOOT_COOLDOWN
    ; PLAY_SFX("shot_normal") - play SFX asset (index=0)
    LDX #0        ; SFX asset index for lookup
    JSR PLAY_SFX_BANKED  ; Play with automatic bank switching
    LDD #0
    STD RESULT
    LBRA IF_END_158
IF_NEXT_159:
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_SNOW2_ACTIVE
    CMPD TMPVAL
